http {
    # Zona 10 MB (~160 ribu IP), batas 10 request/detik per IP
    limit_req_zone $binary_remote_addr zone=api_limit:10m rate=10r/s;

    server {
        listen 80;
        server_name contoh.com;

        location /api/ {
            limit_req zone=api_limit burst=20 nodelay;
            proxy_pass http://127.0.0.1:8080;
        }
    }
}

http {
    # Maks 10 koneksi bersamaan per IP
    limit_conn_zone $binary_remote_addr zone=conn_limit:10m;

    server {
        location / {
            limit_conn conn_limit 10;
            proxy_pass http://127.0.0.1:8080;
        }

        # Download file boleh lebih banyak koneksi
        location /download/ {
            limit_conn conn_limit 50;
            proxy_pass http://127.0.0.1:8080;
        }
    }
}

http {
    # Kunci zona = API key bila ada, kalau tidak pakai IP
    map $http_x_api_key $limit_key {
        default $binary_remote_addr;
        ~.+ $http_x_api_key;
    }

    limit_req_zone $limit_key zone=key_limit:10m rate=30r/s;

    server {
        location /api/v1/ {
            limit_req zone=key_limit burst=30 nodelay;
            proxy_pass http://127.0.0.1:8080;
        }
    }
}

http {
    limit_req_zone $binary_remote_addr zone=api_limit:10m rate=10r/s;
    limit_req_status 429;

    server {
        location /api/ {
            limit_req zone=api_limit burst=20 nodelay;
            # Halaman error khusus untuk yang kena limit
            error_page 429 /rate-limited.html;
            proxy_pass http://127.0.0.1:8080;
        }

        location = /rate-limited.html {
            internal;
            root /var/www/contoh.com/errors;
        }
    }
}

# Cek siapa saja yang kena limit hari ini
# grep 'limiting requests' /var/log/nginx/error.log | awk '{print $7}' | sort | uniq -c | sort -rn | head

http {
    limit_req_zone $binary_remote_addr zone=login_limit:10m rate=1r/s;
    limit_req_zone $binary_remote_addr zone=search_limit:10m rate=2r/s;
    limit_req_zone $binary_remote_addr zone=api_limit:10m rate=10r/s;

    server {
        # Login: sangat ketat, brute force langsung mentok
        location = /login {
            limit_req zone=login_limit burst=5 nodelay;
            proxy_pass http://127.0.0.1:8080;
        }

        # Pencarian: query berat, batasi lebih ketat
        location /search {
            limit_req zone=search_limit burst=5 nodelay;
            proxy_pass http://127.0.0.1:8080;
        }

        # API umum
        location /api/ {
            limit_req zone=api_limit burst=20 nodelay;
            proxy_pass http://127.0.0.1:8080;
        }
    }
}

# IP internal & monitoring tidak kena limit
geo $is_internal {
    default 1;
    10.0.0.0/8 0;
    192.168.0.0/16 0;
    203.0.113.10 0; # IP monitoring
}

# Kunci kosong ('') berarti request tidak dihitung limitnya
map $is_internal $limit_key {
    0 '';
    default $binary_remote_addr;
}

limit_req_zone $limit_key zone=api_limit:10m rate=10r/s;
